agent_def = json.load(open('/tmp/def_agent.json'))
ixp_def = json.load(open('/tmp/def_ixp.json'))
apiwf_def = json.load(open('/tmp/def_apiwf.json'))
context_def = json.load(open('/tmp/def_context.json'))
current = json.load(open('BillingDisputeResolution.flow'))

# IDs
ANALYST_UUID = "7295e887-ea74-4b95-ba1a-7cb92dc03588"
WRITER_UUID = "2375d5e6-e93f-41d3-9fb1-9c2a0ce7ce8e"
CONTEXT_RES_UUID = "17828c41-6286-451b-9f66-58a4cd49b95a"

# IxP inputDefaults
ixp_defaults = ixp_def.get('inputDefaults', {})
ixp_model = ixp_defaults.get('model', {})
# Ensure modelName is non-empty
if not ixp_model.get('modelName'):
    ixp_model['modelName'] = ixp_model.get('modelDisplayName', ixp_defaults.get('modelName', 'invoices-billing'))

# API workflow bindings info
apiwf_bindings = apiwf_def.get('model', {}).get('bindings', {})
apiwf_resource_key = apiwf_bindings.get('resourceKey', 'Shared/uipath-maestro-flow/BillingDispute.FinancialPostingFunction')
apiwf_resource_subtype = apiwf_bindings.get('resourceSubType', 'Api')

# Build the complete flow
flow = {
    "id": current["id"],
    "version": current["version"],
    "name": "BillingDisputeResolution",
    "nodes": [
        # 1. Manual trigger (start)
        {
            "id": "start",
            "type": "core.trigger.manual",
            "typeVersion": "1.0",
            "display": {"label": "Manual trigger"},
            "inputs": {
                "entryPointId": current["nodes"][0]["inputs"]["entryPointId"],
                "isDefaultEntryPoint": True
            },
            "outputs": {
                "output": {
                    "type": "object",
                    "description": "The return value of the trigger.",
                    "source": "=result.response",
                    "var": "output"
                }
            }
        },
        # 2. IxP extraction node
        {
            "id": "extractInvoice",
            "type": ixp_def["nodeType"],
            "typeVersion": ixp_def["version"],
            "display": {"label": "Invoice Extraction"},
            "inputs": {
                "model": ixp_model,
                "modelName": ixp_defaults.get('modelName', 'invoices-billing-f0c606f9-ixp'),
                "projectName": ixp_defaults.get('projectName', 'invoices-billing-f0c606f9-ixp'),
                "folderKey": ixp_defaults.get('folderKey', '79a7d12e-da84-4bf4-ab60-7f34b44dd178'),
                "folderName": ixp_defaults.get('folderName', 'Shared/uipath-maestro-flow/BillingDispute'),
                "versionTag": "",
                "pageRange": "",
                "fileRef": "=js:$vars.start.output.disputedInvoice"
            },
            "outputs": {
                "output": ixp_def.get('outputDefinition', {}).get('output', {"type": "object", "description": "Extraction result", "source": "=result.response", "var": "output"}),
                "error": ixp_def.get('outputDefinition', {}).get('error', {"type": "object", "description": "Error information", "source": "=Error", "var": "error"})
            }
        },
        # 3. Normalize script node
        {
            "id": "normalizeData",
            "type": "core.action.script",
            "typeVersion": script_def["version"],
            "display": {"label": "Normalize Data"},
            "inputs": {
                "script": r"""
const fields = ($vars.extractInvoice.output && $vars.extractInvoice.output.ExtractionResult && $vars.extractInvoice.output.ExtractionResult.ResultsDocument && $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields) ? $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields : [];
const normalized = fields.map(function(f) {
  return {
    Id: f.FieldId,
    Name: f.FieldName,
    Value: f.Values && f.Values.length > 0 ? f.Values[0] : null,
    Type: f.FieldType,
    IsMissing: f.IsMissing,
    Confidence: f.Confidence
  };
});
const invoiceNumberField = fields.find(function(f) { return f.FieldName === 'invoiceNumber' || f.FieldName === 'InvoiceNumber' || f.FieldName === 'invoice_number'; });
let invoiceNumber = invoiceNumberField && invoiceNumberField.Values && invoiceNumberField.Values.length > 0 ? invoiceNumberField.Values[0] : $vars.start.output.webhookPayload.invoice.invoiceNumber;
invoiceNumber = invoiceNumber ? invoiceNumber.trim().toUpperCase() : '';
if (invoiceNumber && !invoiceNumber.startsWith('MCS-')) {
  invoiceNumber = 'MCS-' + invoiceNumber;
}
return { normalizedFields: normalized, normalizedInvoiceNumber: invoiceNumber };
"""
            },
            "outputs": {
                "output": {
                    "type": "object",
                    "description": "The return value of the script",
                    "source": "=result.response",
                    "var": "output"
                },
                "error": {
                    "type": "object",
                    "description": "Error information if the script fails",
                    "source": "=result.Error",
                    "var": "error"
                }
            }
        },
        # 4. CRM Lookup (CLI-configured connector node — preserve as-is from current flow)
        current["nodes"][1],  # crmLookup1
        # 5. ERP Lookup (CLI-configured connector node)
        current["nodes"][2],  # erpLookup1
        # 6. Merge after parallel CRM + ERP
        {
            "id": "mergeResults",
            "type": "core.logic.merge",
            "typeVersion": merge_def["version"],
            "display": {"label": "Merge Lookups"},
            "inputs": {}
        },
        # 7. Discrepancy Detection script
        {
            "id": "detectDiscrepancies",
            "type": "core.action.script",
            "typeVersion": script_def["version"],
            "display": {"label": "Discrepancy Detection"},
            "inputs": {
                "script": r"""
const disputedItems = ($vars.start.output.webhookPayload && $vars.start.output.webhookPayload.dispute && $vars.start.output.webhookPayload.dispute.disputedLineItems) ? $vars.start.output.webhookPayload.dispute.disputedLineItems : [];
const erpRecords = ($vars.erpLookup1.output && $vars.erpLookup1.output.value) ? $vars.erpLookup1.output.value : (Array.isArray($vars.erpLookup1.output) ? $vars.erpLookup1.output : []);
const mismatches = [];
let totalOvercharge = 0;
let totalUndercharge = 0;
disputedItems.forEach(function(item) {
  const erpRow = erpRecords.find(function(r) { return String(r.lineNumber) === String(item.lineNumber); });
  if (erpRow) {
    const contractAmount = parseFloat(erpRow.amount) || 0;
    const disputedAmount = parseFloat(item.amount) || 0;
    const diff = disputedAmount - contractAmount;
    if (Math.abs(diff) > 0.001) {
      mismatches.push({
        lineNumber: item.lineNumber,
        description: item.description,
        disputedAmount: disputedAmount,
        contractAmount: contractAmount,
        difference: diff,
        type: diff > 0 ? 'overcharge' : 'undercharge'
      });
      if (diff > 0) { totalOvercharge += diff; } else { totalUndercharge += Math.abs(diff); }
    }
  }
});
return { mismatches: mismatches, totalOvercharge: totalOvercharge, totalUndercharge: totalUndercharge, hasMismatches: mismatches.length > 0 };
"""
            },
            "outputs": {
                "output": {"type": "object", "description": "Discrepancy detection results", "source": "=result.response", "var": "output"},
                "error": {"type": "object", "description": "Error information", "source": "=result.Error", "var": "error"}
            }
        },
