                "userPrompt": "Analyze the billing dispute and return determination, recommendedAction, autoResolutionEligible, creditAmount, confidence, and rationale.",
                "source": ANALYST_UUID,
                "agentInputVariables": [
                    {"id": "start__output__webhookPayload", "type": "object", "binding": "=$vars.start.output.webhookPayload"},
                    {"id": "normalizeData__output__normalizedFields", "type": "object", "binding": "=$vars.normalizeData.output.normalizedFields"},
                    {"id": "normalizeData__output__normalizedInvoiceNumber", "type": "string", "binding": "=$vars.normalizeData.output.normalizedInvoiceNumber"},
                    {"id": "crmLookup1__output__output", "type": "object", "binding": "=$vars.crmLookup1.output"},
                    {"id": "erpLookup1__output__output", "type": "object", "binding": "=$vars.erpLookup1.output"},
                    {"id": "detectDiscrepancies__output__mismatches", "type": "object", "binding": "=$vars.detectDiscrepancies.output.mismatches"},
                    {"id": "detectDiscrepancies__output__totalOvercharge", "type": "object", "binding": "=$vars.detectDiscrepancies.output.totalOvercharge"},
                    {"id": "detectDiscrepancies__output__totalUndercharge", "type": "object", "binding": "=$vars.detectDiscrepancies.output.totalUndercharge"}
                ],
                "agentOutputVariables": [
                    {"id": "determination", "type": "string"},
                    {"id": "recommendedAction", "type": "string"},
                    {"id": "autoResolutionEligible", "type": "boolean"},
                    {"id": "creditAmount", "type": "number"},
                    {"id": "confidence", "type": "number"},
                    {"id": "rationale", "type": "string"}
                ]
            },
            "outputs": {
                "output": {"type": "object", "description": "Agent response", "source": "=result.response", "var": "output"},
                "error": {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
            }
        },
        # 9. Context node for Dispute Analyst
        {
            "id": "sopContextNode",
            "type": context_def["nodeType"],
            "typeVersion": context_def["version"],
            "display": {"label": "Billing Dispute SOP Index"},
            "inputs": {
                "source": CONTEXT_RES_UUID,
                "indexId": "cc45b9b4-dbf6-47b3-40ac-08debc0cec5b",
                "indexName": "Billing Dispute SOP Index",
                "folderKey": "79a7d12e-da84-4bf4-ab60-7f34b44dd178",
                "folderPath": "Shared/uipath-maestro-flow/BillingDispute",
                "retrievalMode": "semantic",
                "query": {"mode": "prompt", "promptValue": "Query for billing dispute SOP guidance", "textValue": "", "argumentPath": ""},
                "threshold": 0,
                "resultCount": 3,
                "fileExtension": "All",
                "folderPathPrefix": {"mode": "text-builder", "textValue": "", "promptValue": "", "argumentPath": ""}
            }
        },
        # 10. Switch on recommendedAction
        {
