import json

# Fix Dispute Analyst agent.json contentTokens
analyst = json.load(open('7295e887-ea74-4b95-ba1a-7cb92dc03588/agent.json'))
for msg in analyst['messages']:
    if msg['role'] == 'user':
        for tok in msg.get('contentTokens', []):
            if tok.get('type') == 'variable':
                # Add input. prefix if not present
                rs = tok.get('rawString', '')
                if not rs.startswith('input.'):
                    tok['rawString'] = 'input.' + rs
        # Also update the plain content text
        msg['content'] = msg['content'].replace('{{', '{{input.').replace('{{input.input.', '{{input.')
with open('7295e887-ea74-4b95-ba1a-7cb92dc03588/agent.json', 'w') as f:
    json.dump(analyst, f, indent=2)
print("Fixed Dispute Analyst agent.json")

# Fix Resolution Writer agent.json contentTokens
writer = json.load(open('2375d5e6-e93f-41d3-9fb1-9c2a0ce7ce8e/agent.json'))
for msg in writer['messages']:
    if msg['role'] == 'user':
        for tok in msg.get('contentTokens', []):
            if tok.get('type') == 'variable':
                rs = tok.get('rawString', '')
                if not rs.startswith('input.'):
                    tok['rawString'] = 'input.' + rs
        msg['content'] = msg['content'].replace('{{', '{{input.').replace('{{input.input.', '{{input.')
with open('2375d5e6-e93f-41d3-9fb1-9c2a0ce7ce8e/agent.json', 'w') as f:
    json.dump(writer, f, indent=2)
print("Fixed Resolution Writer agent.json")
